def test_render_options_inherited_model(self):
    beatles = Band.objects.create(name='The Beatles', style='rock')
    who = Band.objects.create(name='The Who', style='rock')
    form_class = forms.modelform_factory(
        Compilation,
        fields=['contributors'],
        widgets={
            'contributors': AutocompleteSelectMultiple(
                Compilation._meta.get_field('contributors'), admin.site,
            ),
        },
    )
    form = form_class(initial={'contributors': [beatles.pk]})
    output = form.as_table()
    self.assertIn(
        '<option value="%s" selected>The Beatles</option>' % beatles.pk,
        output,
    )
    self.assertNotIn('The Who', output)

